from lib import *
S = SS('n12')
steps = [
    step("路由数从 10 条到 10 万条(每次 5 个量级)。静态路由 /api/v1/resourceN/list:随机命中一条的耗时 41.2 → 52.3 → 65.9 → 89.1 → 122.7 ns;带参数的 /svcN/items/:id:45.7 → 58.6 → 77.4 → 102.2 → 135.8 ns。路由数增长 1 万倍,耗时约 3 倍。404(/api/v1/nothing/list)始终 37 ns 左右,不随路由数变化。10 万条静态路由注册耗时 43.5 ms、110000 个节点、堆增加 22.8 MB;参数路由 53.8 ms、210000 个节点、33.2 MB。对照:Go 的 map 精确匹配 7.0 → 12.2 ns,但只能匹配静态路径。", t=tl(S(1)), mark=lidx(S(1), '122.7', '135.8'), done=lidx(S(1), '41.2', '45.7', '7.0 ns/op', '12.2 ns/op'), b=bars([['10 条', 41.2, '41.2 ns'], ['100 条', 52.3, '52.3 ns'], ['1000 条', 65.9, '65.9 ns'], ['1 万条', 89.1, '89.1 ns'], ['10 万条', 122.7, '122.7 ns']], 135, done=[0, 1, 2], mark=[3, 4]), kv=KV([['10 → 10 万条', '命中 41 → 123 ns(静态),46 → 136 ns(参数)'], ['404', '37 ns,不随路由数变'], ['10 万条静态', '注册 43.5 ms,堆 22.8 MB']], ['10 → 10 万条'])),
    step("为什么变慢?树的深度只从 4 层增加到 6 层(最后一条路由 resource999 / resource99999)。同一棵树里重复查同一条路由:1000 条的树 39.1 ns,10 万条的树 44.0 ns,几乎没变;轮流查随机的 1024 条:66.2 ns 与 122.9 ns。也就是说多出来的耗时主要出现在“每次访问不同路径”的时候。", t=tl(S(2)), mark=lidx(S(2), '随机查 1024 条轮流:122.9', '随机查 1024 条轮流:66.2'), done=lidx(S(2), '重复查同一条:39.1', '重复查同一条:44.0', '树最深'), b=bars([['1000 条:重复查同一条', 39.1, '39.1 ns'], ['10 万条:重复查同一条', 44.0, '44.0 ns'], ['1000 条:轮流查 1024 条', 66.2, '66.2 ns'], ['10 万条:轮流查 1024 条', 122.9, '122.9 ns']], 122.9, done=[0, 1], mark=[2, 3]), kv=KV([['树深', '4 层 → 6 层'], ['同一条重复查', '39.1 → 44.0 ns,几乎不变'], ['轮流查不同路径', '66.2 → 122.9 ns']], ['轮流查不同路径'])),
]
A = mkartn('n12', 12, 'Gin,路由树,性能,路由数量,基准测试,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测路由数量从 10 条增长到 10 万条时匹配耗时的变化:静态路由随机命中一条从 41 ns 增长到 123 ns(约 3 倍),404 始终 37 ns;10 万条路由注册 43.5 ms、堆增加 22.8 MB;同一路径重复查询几乎不变(39 → 44 ns),变慢主要出现在访问不同路径时。',
    '路由树的耗时和路由条数有什么关系?这篇把路由数从 10 条加到 10 万条,分别量注册耗时、内存、随机命中一条路由和 404 的耗时,再拆开看变慢到底是树变深还是别的原因,并和 Go 的 map 精确匹配做个对照。',
    [('41 → 123 ns', '10 条到 10 万条静态路由时,随机命中一条路由的耗时'), ('37 ns', '同一批树里 404 请求的耗时(不随路由数变化)'), ('22.8 MB', '10 万条静态路由注册后的堆增量')],
    [('一万倍的路由,三倍的耗时', '<p>匹配耗时不是常数,但增长得很慢:路由数增加 1 万倍,命中一条路由的耗时约 3 倍(静态 41 → 123 ns,带参数 46 → 136 ns)。注册 10 万条路由只要几十毫秒,堆增加二三十 MB(静态路由 110000 个节点,带参数的 210000 个)。作为对照,Go 的 <code>map</code> 精确匹配是 7 → 12 ns,但它只能匹配完整的静态路径,取不了参数,也做不了前缀共享。</p><p>404 的耗时恒定约 37 ns,是因为这条测试路径(<code>/api/v1/nothing/list</code>)在树的前几层就匹配失败,不能代表所有 404 的情形。</p>'),
     ('变慢的原因', '<p>树的深度只从 4 层增加到 6 层。同一棵树里<b>重复</b>查同一条路由,耗时几乎不变(39.1 → 44.0 ns),可见深度增加本身只贡献了几纳秒;而轮流查 1024 条不同的路径时从 66.2 ns 变成 122.9 ns,差距主要出现在访问分散的时候。我的判断是 CPU 缓存和分支预测的影响(树大了以后每次访问的节点更分散),但我没有用性能计数器验证这个解释,所以它是推测。</p>')],
    steps,
    [ENV_N_GIN + '。DumpTree 用来数节点和深度(源码副本里加的只读函数);基准是 testing.Benchmark 测 Engine.ServeHTTP(丢弃输出的 ResponseWriter),每个数字是 5 轮的中位数;命中的耗时是从 1024 条随机选出的路径中轮流查询;堆增量是注册前后各 GC 两次后的 HeapAlloc 差;每种路由形状、每个数量各跑一次',
     '没有验证:真实业务的路由形状(长前缀、很多共享前缀)下的曲线;缓存和分支预测的解释(没有 perf / 计数器);多核并发下的耗时;不同 Go 版本、不同 CPU(只在一台 macOS arm64 上测)的数字;路由数超过 10 万条的情形'],
    '路由数量')
